# push_to_assase.ps1
# Clones https://github.com/ronnyklemesu7-hub/Assase, writes all fixed files, commits and pushes.
# Usage: powershell -ExecutionPolicy Bypass -File .\push_to_assase.ps1
# Requires git in PATH and GitHub credentials (token or SSH).

$ErrorActionPreference = "Stop"
$REPO_URL  = "https://github.com/ronnyklemesu7-hub/Assase.git"
$BRANCH    = "main"
$CLONE_DIR = Join-Path $env:TEMP "Assase_push"

function Write-Step($m) { Write-Host "" ; Write-Host "  --> $m" -ForegroundColor Cyan }
function Write-Ok($m)   { Write-Host "  [OK] $m" -ForegroundColor Green }
function Write-Warn($m) { Write-Host "  [!!] $m" -ForegroundColor Yellow }

Write-Host ""
Write-Host "============================================" -ForegroundColor Green
Write-Host "  ASAASE - Pushing Debugged Files" -ForegroundColor White
Write-Host "============================================" -ForegroundColor Green

# Step 1 - Clone
Write-Step "Cloning repo"
if (Test-Path $CLONE_DIR) { Remove-Item $CLONE_DIR -Recurse -Force }
git clone $REPO_URL $CLONE_DIR
Set-Location $CLONE_DIR
git checkout $BRANCH
Write-Ok "Cloned into $CLONE_DIR"

# Step 2 - Write files using base64 stored in PS1 variables
Write-Step "Writing fixed files"

function Write-B64File {
    param([string]$RelPath, [string]$B64)
    $dest = Join-Path $CLONE_DIR ($RelPath -replace "/", "\")
    $dir  = Split-Path $dest -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
    $bytes = [Convert]::FromBase64String($B64)
    [System.IO.File]::WriteAllBytes($dest, $bytes)
    Write-Ok "  $RelPath"
}

$file_b64_0 = ""
Write-B64File -RelPath "dashboard_api.py" -B64 $file_b64_0
Remove-Variable file_b64_0

$file_b64_1 = ""
Write-B64File -RelPath "dashboard.html" -B64 $file_b64_1
Remove-Variable file_b64_1

$file_b64_2 = ""
Write-B64File -RelPath "dashboard/src/components/ControlCenter.tsx" -B64 $file_b64_2
Remove-Variable file_b64_2

$file_b64_3 = ""
Write-B64File -RelPath "dashboard/src/components/Sidebar.tsx" -B64 $file_b64_3
Remove-Variable file_b64_3

$file_b64_4 = ""
Write-B64File -RelPath "dashboard/src/components/MaintenanceForecast.tsx" -B64 $file_b64_4
Remove-Variable file_b64_4

$file_b64_5 = ""
Write-B64File -RelPath "dashboard/src/components/WaterGauge.tsx" -B64 $file_b64_5
Remove-Variable file_b64_5

$file_b64_6 = ""
Write-B64File -RelPath "dashboard/src/components/Dashboard.tsx" -B64 $file_b64_6
Remove-Variable file_b64_6

$file_b64_7 = ""
Write-B64File -RelPath "dashboard/src/components/DistributionView.tsx" -B64 $file_b64_7
Remove-Variable file_b64_7

$file_b64_8 = ""
Write-B64File -RelPath "dashboard/src/components/asaase/ControlHub.tsx" -B64 $file_b64_8
Remove-Variable file_b64_8

$file_b64_9 = ""
Write-B64File -RelPath "dashboard/src/components/asaase/AsaaseView.tsx" -B64 $file_b64_9
Remove-Variable file_b64_9

$file_b64_10 = ""
Write-B64File -RelPath "dashboard/src/components/asaase/AlertList.tsx" -B64 $file_b64_10
Remove-Variable file_b64_10

$file_b64_11 = ""
Write-B64File -RelPath "dashboard/src/components/asaase/ReportViewer.tsx" -B64 $file_b64_11
Remove-Variable file_b64_11

$file_b64_12 = ""
Write-B64File -RelPath "dashboard/src/asaaseApi.ts" -B64 $file_b64_12
Remove-Variable file_b64_12

$file_b64_13 = ""
Write-B64File -RelPath "dashboard/src/index.css" -B64 $file_b64_13
Remove-Variable file_b64_13


# Step 3 - Remove dead file
Write-Step "Cleaning up"
$appCss = Join-Path $CLONE_DIR "dashboard\src\App.css"
if (Test-Path $appCss) { Remove-Item $appCss -Force; Write-Ok "  Removed App.css" }

# Step 4 - Commit and push
Write-Step "Staging"
git add -A
Write-Ok "git add done"

Write-Step "Committing"
$changed = git status --porcelain
if (-not $changed) {
    Write-Warn "Nothing to commit"
} else {
    git commit -m "fix: full debug pass 29 bugs fixed plus HTML dashboard"
    Write-Ok "Committed"
}

Write-Step "Pushing"
git push origin $BRANCH
Write-Ok "Pushed to origin/$BRANCH"

Write-Host ""
Write-Host "============================================" -ForegroundColor Green
Write-Host "  Done! https://github.com/ronnyklemesu7-hub/Assase" -ForegroundColor Cyan
Write-Host "============================================" -ForegroundColor Green